import{_ as o,c as a,o as e,ae as n}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Sorting","description":"Sorting","frontmatter":{"title":"Sorting","description":"Sorting"},"headers":[],"relativePath":"guide/styling-design/sorting.md","filePath":"guide/styling-design/sorting.md"}'),r={name:"guide/styling-design/sorting.md"};function s(i,t,l,g,d,h){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h1><p>The <strong>Sorting</strong> <strong>Method</strong> is one of the essential features of the <strong>Other</strong> tab. Move to the <strong>Select Sorting Method</strong> option to sort table data in various ways. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-sorting-options-585x1024.png" alt="New Ui table sorting options"> The sorting Method has three options to sort by - <strong>Created at</strong>,** By Column**, and <strong>Manual Sort</strong>.</p><h2 id="by-column" tabindex="-1"><strong>By Column</strong> <a class="header-anchor" href="#by-column" aria-label="Permalink to &quot;**By Column**&quot;">​</a></h2><p>From the dropdown, you can choose any <strong>Column</strong> as per your needs. You can also choose <strong>Sort type</strong> by selecting ascending or Descending way.</p><h2 id="by-created-at" tabindex="-1"><strong>By Created at</strong> <a class="header-anchor" href="#by-created-at" aria-label="Permalink to &quot;**By Created at**&quot;">​</a></h2><p>In this option, two sort types are available - Show New Items First &amp; Show Old Items First.</p><h2 id="sort-manually" tabindex="-1"><strong>Sort Manually</strong> <a class="header-anchor" href="#sort-manually" aria-label="Permalink to &quot;**Sort Manually**&quot;">​</a></h2><p>You can sort the table data from <strong>Table Rows</strong> manually. It&#39;s a pro feature. Click the <strong>Sort</strong> <strong>Manually</strong> checkbox to enable sorting the data using the drag-and-drop feature. Just hover over any row and manually rearrange them. <img src="https://ninjatables.com/wp-content/uploads/2025/05/new-Ui-table-manual-sort-1024x405.webp" alt="new Ui table manual sort"> This is how easily anyone can utilize the <strong>Sorting Method</strong>!</p>',8)])])}const p=o(r,[["render",s]]);export{u as __pageData,p as default};
